(()=>{
 let busy=false, excludedOpen=false, scopeOpen=false;const el=id=>document.getElementById(id);
 async function read(path){const r=await fetch(path);if(!r.ok)throw Error('Unavailable');return r.json()}
 async function refresh(){if(busy)return;busy=true;try{const [feed,manual,alerts,output,scope]=await Promise.allSettled(['/api/summary','/api/manual-edits','/api/alert-assessments','/api/pipeline-output','/api/pipeline-scope'].map(read));
 const scopeBox=el('run-scope');scopeBox.replaceChildren();if(scope.status==='fulfilled'){const d=scope.value,line=document.createElement('p');line.textContent='Next run: '+d.ready_edits.length+' feed edits included'+(d.reflected_edits?.length?' ('+d.reflected_edits.length+' already reflected)':'')+' · '+d.ready_service.length+' service changes ready'+(d.blocked.length?' · '+d.blocked.length+' alerts not included':'')+(d.missing_edits.length?' · '+d.missing_edits.length+' feed edits need review':'')+(d.stale?' · Feed changed; reassess alerts':'');scopeBox.append(line);if(d.blocked.length||d.missing_edits.length){const details=document.createElement('details'),summary=document.createElement('summary'),list=document.createElement('ul');details.open=scopeOpen;details.addEventListener('toggle',()=>{scopeOpen=details.open});summary.textContent='Why items are not included';const groups={};for(const x of d.blocked)(groups[x.reason]??=[]).push(x.change_id);for(const [reason,ids] of Object.entries(groups)){const li=document.createElement('li');li.textContent=reason+' ('+ids.length+'): '+ids.join(', ');list.append(li)}if(d.missing_edits.length){const li=document.createElement('li');li.textContent='Feed edit route not found: '+d.missing_edits.join(', ');list.append(li)}details.append(summary,list);scopeBox.append(details)}}else scopeBox.textContent='Could not load the next run summary.';
 const result=output.status==='fulfilled'?output.value:null;const tracked=new Set();if(manual.status==='fulfilled')for(const item of manual.value.items||[])if(item.active||item.applied)tracked.add(item.id);
 if(alerts.status==='fulfilled'&&alerts.value)for(const item of alerts.value.items||[]){const assessment=item.assessment||{};if(item.decision!=='no'&&!['no_schedule_modeling_needed','no_schedule_change','not_recommended','not_modelable'].includes(assessment.status))tracked.add(item.change_id)}
 const applied=new Set(result?.tasks||[]);for(const id of applied)tracked.add(id);const edits=[...applied].filter(id=>id.startsWith('edit-')).length,service=applied.size-edits;
 el('pipeline-summary').textContent=result?`${edits} feed edit${edits===1?'':'s'} · ${service} service change${service===1?'':'s'} in the last output`:'';el('pipeline-progress').textContent=result?`${applied.size} / ${tracked.size} tracked tasks in the last output`:`${tracked.size} tracked tasks · no completed output`;
 el('pipeline-download').hidden=!result;el('pipeline-output-state').textContent=result?`Last run · ${result.tasks.length} applied tasks${result.excluded_alerts?.length?' · Partial output: '+result.excluded_alerts.length+' alerts not included':''}`:'Run the pipeline to create an output GTFS.';el('pipeline-result').textContent=result?'Output SHA-256: '+result.sha256:'';
 if(result?.excluded_alerts?.length){const details=document.createElement('details'),summary=document.createElement('summary'),list=document.createElement('ul');details.open=excludedOpen;details.addEventListener('toggle',()=>{excludedOpen=details.open});summary.textContent='Alerts not included ('+result.excluded_alerts.length+')';for(const item of result.excluded_alerts){const li=document.createElement('li');li.textContent=item.change_id+' — '+item.reason;list.append(li)}details.append(summary,list);el('pipeline-result').append(details)}
 }finally{busy=false}}
 refresh();if(!window.gtfsHostedRequest)setInterval(refresh,5000);window.addEventListener('pipeline-updated',refresh);
})();
